"""Wythoff's game: decide LOSE, else return lexicographically smallest winning move."""


def solve(text: str) -> str:
    a, b = (int(x) for x in text.split()[:2])
    # losing positions (cold positions) generated by Beatty sequences
    import math

    cold = set()
    n = 0
    while True:
        n += 1
        c = n + int(math.floor(n * ((1 + 5 ** 0.5) / 2)))
        p = (n, n + c - n)
        p = (n, c)
        if p[0] > 25 and p[1] > 25:
            break
        cold.add(p)
        cold.add((p[1], p[0]))
    if (a, b) in cold:
        return "LOSE"
    best = None
    # (i) remove from one pile only
    for i in range(0, a + 1):
        if i == 0:
            continue
        if (a - i, b) in cold:
            if best is None or (i, 0) < best:
                best = (i, 0)
    for j in range(0, b + 1):
        if j == 0:
            continue
        if (a, b - j) in cold:
            if best is None or (0, j) < best:
                best = (0, j)
    # (ii) remove the same number from both piles
    for t in range(1, min(a, b) + 1):
        if (a - t, b - t) in cold:
            if best is None or (t, t) < best:
                best = (t, t)
    if best is None:
        return "LOSE"
    return "WIN %d %d" % best
